set-variable.value:
@{
    if ((context.Api.Path ?? "").Trim('/') != "ai4ia-photo-avatars-v1" ||
        context.Subscription == null ||
        context.Subscription.Id != "__AI4IA_PHOTO_AVATAR_SUBSCRIPTION_ID__") { return ""; }
    string operation = context.Operation.Id;
    string expected =
        operation == "photo-avatar-features" ? "GET /features" :
        operation == "photo-avatar-project-read" ? "GET /project" :
        operation == "photo-avatar-project-create" ? "PUT /project" :
        operation == "photo-avatar-create" ? "PUT /photoavatars" :
        operation == "photo-avatar-read" ? "GET /photoavatars" :
        operation == "photo-avatar-delete" ? "DELETE /photoavatars" :
        "";
    string query = context.Request.OriginalUrl.QueryString;
    if (expected.Length == 0 || (!string.IsNullOrEmpty(query) && query != "?")) { return ""; }
    var match = System.Text.RegularExpressions.Regex.Match(context.Request.OriginalUrl.Path,
        @"\A/ai4ia-photo-avatars-v1/(features|project|photoavatars/(ai4ia-[0-9a-f]{20}))\z");
    if (!match.Success) { return ""; }
    string route = match.Groups[2].Success ? "/photoavatars" : "/" + match.Groups[1].Value;
    if (context.Request.Method + " " + route != expected) { return ""; }
    if (match.Groups[2].Success && (!context.Request.MatchedParameters.ContainsKey("avatarId") ||
        context.Request.MatchedParameters["avatarId"] != match.Groups[2].Value)) { return ""; }
    byte[] bytes = context.Request.Body == null
        ? new byte[0] : context.Request.Body.As<byte[]>(preserveContent: true);
    if (operation != "photo-avatar-create") { return bytes.Length == 0 ? operation : ""; }
    if (bytes.Length == 0 || bytes.Length > 16384) { return ""; }
    JObject body;
    try { body = JObject.Parse(System.Text.Encoding.UTF8.GetString(bytes)); }
    catch (Exception) { return ""; }
    JObject properties = body["properties"] as JObject;
    if (body.Properties().Count() != 1 || properties == null) { return ""; }
    JToken prompt = properties["prompt"];
    if (prompt == null || prompt.Type != JTokenType.String) { return ""; }
    string text = prompt.Value<string>();
    if (text.Trim().Length == 0 || text.Length > 1000) { return ""; }
    foreach (JProperty item in properties.Properties()) {
        if (item.Name == "prompt") { continue; }
        string[] allowed =
            item.Name == "gender" ? new string[] { "Male", "Female" } :
            item.Name == "age" ? new string[] { "YoungAdult", "MiddleAged", "Senior" } :
            item.Name == "ethnicity" ? new string[] { "Asian", "White", "BlackAndAfricanAmerican", "SouthAsian", "MiddleEastern", "HispanicAndLatinx" } :
            item.Name == "style" ? new string[] { "Realistic", "DigitalIllustration", "Stylized3D" } :
            null;
        if (allowed == null || item.Value.Type != JTokenType.String ||
            !allowed.Contains(item.Value.Value<string>())) { return ""; }
    }
    return operation;
}

when.set-body:
@{
    JObject body = JObject.Parse(System.Text.Encoding.UTF8.GetString(
        context.Request.Body.As<byte[]>(preserveContent: true)));
    JObject properties = (JObject)body["properties"];
    JObject canonical = new JObject();
    foreach (string name in new string[] { "prompt", "gender", "age", "ethnicity", "style" }) {
        JToken value = properties[name];
        if (value != null) { canonical.Add(new JProperty(name, value.Value<string>())); }
    }
    return new JObject(new JProperty("properties", canonical)).ToString(
        Newtonsoft.Json.Formatting.None);
}

set-variable.value:
@{
      var supplied = context.Request.Headers.GetValueOrDefault("x-correlation-id", "");
      return !String.IsNullOrWhiteSpace(supplied) && supplied.Length <= 128
        ? supplied
        : context.RequestId.ToString();
    }
